package com.school.management.entity; import jakarta.persistence.*;import jakarta.validation.constraints.*;
@Entity public class Teacher { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank private String employeeNo; @NotBlank private String fullName; @Email private String email; @JsonProperty(access = JsonProperty.Access.WRITE_ONLY) private String password; private String phone,department,specialization; public Teacher(){} public Long getId(){return id;} public String getEmployeeNo(){return employeeNo;} public void setEmployeeNo(String v){employeeNo=v;} public String getFullName(){return fullName;} public void setFullName(String v){fullName=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPassword(){return password;} public void setPassword(String v){password=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getDepartment(){return department;} public void setDepartment(String v){department=v;} public String getSpecialization(){return specialization;} public void setSpecialization(String v){specialization=v;} }
